CREATE DATABASE IF NOT EXISTS weather_system DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE weather_system;
DROP TABLE IF EXISTS device_alert, maintain_plan, oper_log, notice, weather_data, maintain, device, station, sys_user;
CREATE TABLE sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'viewer', name VARCHAR(50), phone VARCHAR(30), create_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE station (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, address VARCHAR(255), longitude DECIMAL(10,6), latitude DECIMAL(10,6), manager VARCHAR(50));
CREATE TABLE device (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, type VARCHAR(30), model VARCHAR(80), manufacturer VARCHAR(100), station_id BIGINT, purchase_date DATE, status VARCHAR(20) DEFAULT 'normal', remark VARCHAR(255), CONSTRAINT fk_device_station FOREIGN KEY(station_id) REFERENCES station(id) ON DELETE SET NULL);
CREATE TABLE maintain (id BIGINT PRIMARY KEY AUTO_INCREMENT, device_id BIGINT NOT NULL, fault_description VARCHAR(500), maintainer VARCHAR(50), content VARCHAR(500), report_time DATETIME, finish_time DATETIME, cost DECIMAL(10,2), result VARCHAR(100), FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE);
CREATE TABLE weather_data (id BIGINT PRIMARY KEY AUTO_INCREMENT, device_id BIGINT NOT NULL, collect_time DATETIME NOT NULL, temperature DECIMAL(6,2), humidity DECIMAL(6,2), wind_speed DECIMAL(6,2), rainfall DECIMAL(8,2), pressure DECIMAL(8,2), FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE);
CREATE TABLE oper_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, operator VARCHAR(50), action VARCHAR(100), target VARCHAR(100), operate_time DATETIME DEFAULT CURRENT_TIMESTAMP, ip VARCHAR(50));
CREATE TABLE notice (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200), content TEXT, publisher VARCHAR(50), publish_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE device_alert (id BIGINT PRIMARY KEY AUTO_INCREMENT, device_id BIGINT NOT NULL, type VARCHAR(50), level VARCHAR(20), message VARCHAR(500), status VARCHAR(20) DEFAULT 'open', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, acknowledged_by VARCHAR(50), acknowledged_at DATETIME, FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE);
CREATE TABLE maintain_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT, device_id BIGINT NOT NULL, title VARCHAR(200), cycle_days INT, next_date DATE, owner VARCHAR(50), status VARCHAR(20) DEFAULT 'pending', remark VARCHAR(500), create_time DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE);
